#![no_std]

use voidhash_ui::prelude::*;

/// Selectable plans: tapping one selects it, and the button buys it.
#[component(
    title = "Plan picker",
    description = "Selectable plans.",
    events(selected(product_id: string)),
    capabilities(commerce),
    traits(frame(resize = "width"), appearance, effects),
    size(width = "fill", height = "hug")
)]
pub fn PlanPicker(cx: Cx, plans: Vec<Product>, #[prop(default = "#7c3aed")] accent: Color) -> View {
    let selected = cx.state(|| plans.first().map(|plan| plan.id.clone()));
    let current = selected.get();
    vstack()
        .spacing(12)
        .children(plans.iter().map(|plan| {
            let id = plan.id.clone();
            hstack()
                .key(&plan.id)
                .child(text(&plan.title).font(Font::HEADLINE))
                .child(spacer())
                .child(text(plan.price_per_period()))
                .border(if current.as_ref() == Some(&plan.id) { 2 } else { 1 }, accent)
                .corner_radius(14)
                .on_tap(move |cx| {
                    selected.set(Some(id.clone()));
                    cx.emit("selected", object([("productId", Value::from(&id))]))
                })
        }))
        .child(button("Continue").prominent().on_tap(move |cx| {
            if let Some(id) = selected.get() {
                cx.purchase(&id);
            }
        }))
}

